import 'dart:math' as math;
import 'package:flutter/material.dart';
const Set<String> codeFoodPictogramBatch29Ids=<String>{'jordanian_mansaf','jordanian_rashouf','jordanian_makmoura'};
bool hasCodeFoodPictogramBatch29(String foodId)=>codeFoodPictogramBatch29Ids.contains(foodId);
class FoodPictogramPainterBatch29 extends CustomPainter{final String foodId;const FoodPictogramPainterBatch29(this.foodId);Paint f(Color c)=>Paint()..color=c..isAntiAlias=true;Paint s(Color c,double w)=>Paint()..color=c..style=PaintingStyle.stroke..strokeWidth=w..strokeCap=StrokeCap.round..isAntiAlias=true;@override void paint(Canvas c,Size z){final d=math.min(z.width,z.height);c.save();c.translate((z.width-d)/2,(z.height-d)/2);c.scale(d/100,d/100);c.drawShadow(Path()..addOval(const Rect.fromLTWH(18,78,64,6)),Colors.black.withValues(alpha:.14),4,false);switch(foodId){case 'jordanian_mansaf':c.drawOval(const Rect.fromLTWH(15,48,70,30),f(const Color(0xFFF0E0B2)));c.drawOval(const Rect.fromLTWH(23,45,54,24),f(const Color(0xFFD9B65F)));c.drawOval(const Rect.fromLTWH(35,38,30,20),f(const Color(0xFF8B5A3C)));for(final p in <Offset>[Offset(30,53),Offset(68,54),Offset(39,65),Offset(60,64)])c.drawCircle(p,3,f(const Color(0xFFC79B4B)));break;case 'jordanian_rashouf':c.drawOval(const Rect.fromLTWH(22,38,56,40),f(const Color(0xFFF0E1B9)));c.drawOval(const Rect.fromLTWH(25,40,50,28),f(const Color(0xFFD8C58C)));for(final p in <Offset>[Offset(35,51),Offset(47,57),Offset(60,50),Offset(65,60)])c.drawCircle(p,3,f(const Color(0xFF8D6E4A)));break;case 'jordanian_makmoura':c.drawPath(Path()..moveTo(22,68)..lineTo(50,31)..lineTo(78,68)..close(),f(const Color(0xFFD5A04B)));c.drawPath(Path()..moveTo(29,64)..lineTo(50,39)..lineTo(71,64)..close(),f(const Color(0xFFF0CF83)));c.drawLine(const Offset(32,57),const Offset(68,57),s(const Color(0xFF9A653D),3));break;}c.restore();}@override bool shouldRepaint(covariant FoodPictogramPainterBatch29 o)=>o.foodId!=foodId;}
